-- ============ Part 2: rules, security (hand-written) ============

ALTER TABLE users
  ADD CONSTRAINT users_vo_status_check CHECK (vo_status IN ('AUTO', 'AWAY', 'DND'));
ALTER TABLE offices
  ADD CONSTRAINT offices_proximity_radius_check CHECK (proximity_radius BETWEEN 48 AND 320);
ALTER TABLE rooms
  ADD CONSTRAINT rooms_type_check CHECK (type IN ('OPEN', 'MEETING', 'PRIVATE', 'BROADCAST')),
  ADD CONSTRAINT rooms_access_mode_check CHECK (access_mode IN ('OPEN', 'KNOCK', 'INVITE', 'PASSWORD')),
  ADD CONSTRAINT rooms_capacity_check CHECK (capacity BETWEEN 1 AND 500),
  -- A password room always has a password; no other room keeps one.
  ADD CONSTRAINT rooms_password_check CHECK ((access_mode = 'PASSWORD') = (password_hash IS NOT NULL));

DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['offices', 'rooms', 'room_invites', 'desks'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I FOR ALL
         USING (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)
         WITH CHECK (org_id = NULLIF(current_setting(''app.org_id'', true), '''')::uuid)',
      t || '_org_policy', t);
  END LOOP;
END
$$;
GRANT SELECT, INSERT, UPDATE ON offices TO hrvo_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON rooms, room_invites, desks TO hrvo_app;

-- Rooms, desks and invites must point at the same organisation's office and people.
CREATE FUNCTION fn_office_same_org() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  -- One branch per table: PL/pgSQL resolves NEW.<column> even when an earlier AND term is false.
  IF TG_TABLE_NAME = 'rooms' THEN
    IF NOT EXISTS (SELECT 1 FROM offices o WHERE o.id = NEW.office_id AND o.org_id = NEW.org_id) THEN
      RAISE EXCEPTION 'office belongs to another organisation';
    END IF;
  ELSIF TG_TABLE_NAME = 'desks' THEN
    IF NOT EXISTS (SELECT 1 FROM offices o WHERE o.id = NEW.office_id AND o.org_id = NEW.org_id) THEN
      RAISE EXCEPTION 'office belongs to another organisation';
    END IF;
    IF NEW.assigned_user_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM users u WHERE u.id = NEW.assigned_user_id AND u.org_id = NEW.org_id) THEN
        RAISE EXCEPTION 'desk assignee belongs to another organisation';
      END IF;
    END IF;
  ELSIF TG_TABLE_NAME = 'room_invites' THEN
    IF NOT EXISTS (SELECT 1 FROM rooms r WHERE r.id = NEW.room_id AND r.org_id = NEW.org_id)
       OR NOT EXISTS (SELECT 1 FROM users u WHERE u.id = NEW.user_id AND u.org_id = NEW.org_id) THEN
      RAISE EXCEPTION 'room invite crosses organisations';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER rooms_same_org BEFORE INSERT OR UPDATE ON rooms FOR EACH ROW EXECUTE FUNCTION fn_office_same_org();
CREATE TRIGGER desks_same_org BEFORE INSERT OR UPDATE ON desks FOR EACH ROW EXECUTE FUNCTION fn_office_same_org();
CREATE TRIGGER room_invites_same_org BEFORE INSERT OR UPDATE ON room_invites FOR EACH ROW EXECUTE FUNCTION fn_office_same_org();
